figures.asymptoteSource:
// The graph of f(x) = sqrt(x-2), drawn only where the rule is real.
// Two-argument size fixes the output box at 320 x 240, so the declared
// aspect ratio 4/3 is exact and the reserved space cannot drift.
size(320,240);
pair O=(0,0);
import graph;
real f(real x){return sqrt(x-2);}
pair A=(-0.5,-1.2), B=(6.6,4.4);
draw(A--B,Arrow);
label("$x$",B,SE);
draw((0,-1.2)--(0,4.4),Arrow);
label("$y$",(0,4.4),N);
draw(graph(f,2,6.4,200),blue);
dot((2,0), black+2.5pt);
label("$2$",(2,-0.9),S);
dot((0,0), black+2pt);
label("$O$",(0,0),SW);
label("$y=\\sqrt{x-2}$",(5.4,3.7),N);
